use std::borrow::Cow;

use lb_binary_codec::canonical::{
    CodecExamples, CodecFixture, CodecFixtures, codec_fixtures, decode_fixture_hex, sealed,
};
use lb_cryptarchia_engine::Slot;
use lb_groth16::Fr;
use lb_key_management_system_keys::keys::ZkPublicKey;

use crate::{
    block::{
        Block, BlockTransactionReferences, BlockTransactions, Proposal, References, UncleHeaders,
    },
    header::{ContentId, Header, HeaderId},
    mantle::{
        TxHash,
        traits::{Hashable, StorageSize},
    },
    proofs::leader_proof::Groth16LeaderProof,
};

/// The three real references every reference fixture below is built from.
fn three_references() -> BlockTransactionReferences {
    [
        TxHash([0x01u8; 32]).prefix(),
        TxHash([0x02u8; 32]).prefix(),
        TxHash([0x03u8; 32]).prefix(),
    ]
    .into()
}

/// The uncle maximum the fixtures are built and decoded under.
const FIXTURE_MAX_UNCLES: u8 = 4;

fn three_uncle_headers() -> UncleHeaders {
    UncleHeaders::try_new(
        vec![header(0x66), header(0x77), header(0x88)],
        FIXTURE_MAX_UNCLES,
    )
    .unwrap()
}

fn header(id: u8) -> Header {
    Header::new(
        HeaderId::from([id; 32]),
        ContentId::from([0x22u8; 32]),
        Slot::from(42u64),
        Groth16LeaderProof::from_parts(
            lb_pol::PoLProof::from_bytes(&[0x22u8; _]),
            Fr::from(0x5555u64),
            ZkPublicKey::new(Fr::from(0x4444u64)),
        ),
    )
}

codec_fixtures!(
    References,
    Self { mempool_transactions: three_references() } => "0300010101010101010101010101010101010202020202020202020202020202020203030303030303030303030303030303"
);

// Layout: `count (1B LE) || count x header`.
codec_fixtures!(
    UncleHeaders,
    context = FIXTURE_MAX_UNCLES,
    Self::empty() => "00",
    three_uncle_headers() => ""
);

// `header || uncle_headers (1B count + count * 265B) || references (50B)`,
// 1111 bytes with three uncles.
//
// `references` is a `BoundedVec` capped at 1024, so it carries a 2-byte
// little-endian length prefix ahead of its 3 * 16-byte hash prefixes.
codec_fixtures!(
    Proposal,
    context = FIXTURE_MAX_UNCLES,
    Self {
        header: header(0x00),
        uncle_headers: three_uncle_headers(),
        references: References { mempool_transactions: three_references() },
    } => ""
);

/// A block of slot 42 referencing three uncles and carrying no transactions, so
/// that it decodes and checks out whatever its transaction type.
fn block<Tx>() -> Block<Tx>
where
    Tx: Hashable<Hash = TxHash> + StorageSize,
{
    let proof = Groth16LeaderProof::from_parts(
        lb_pol::PoLProof::from_bytes(&[0x22u8; _]),
        Fr::from(0x5555u64),
        ZkPublicKey::new(Fr::from(0x4444u64)),
    );
    Block::create(
        HeaderId::from([0x00u8; 32]),
        Slot::from(42u64),
        three_uncle_headers(),
        proof,
        BlockTransactions::empty(),
    )
    .expect("The fixture block is valid.")
}

// `header (265B) || uncle_headers (1B count + 3 * 265B) || transactions (2B
// count)`, 1063 bytes.
const BLOCK_HEX: &str = "";

impl<Tx> sealed::Sealed for Block<Tx> {}

impl<Tx> CodecExamples for Block<Tx>
where
    Tx: Hashable<Hash = TxHash> + StorageSize,
{
    fn fixtures() -> CodecFixtures<Self> {
        [CodecFixture {
            value: block(),
            bytes: Cow::Owned(decode_fixture_hex(BLOCK_HEX)),
        }]
        .into()
    }
}

#[cfg(test)]
mod tests {
    use lb_binary_codec::canonical::assert_codec_fixtures_with;

    use super::FIXTURE_MAX_UNCLES;
    use crate::{
        block::Block,
        mantle::{
            ledger::verification_mode::StandardMode,
            transactions::{SignedOps, states::Preverified},
        },
    };

    #[test]
    fn block_fixtures_round_trip() {
        assert_codec_fixtures_with::<Block<SignedOps<Preverified, StandardMode>>, _>(|| {
            (FIXTURE_MAX_UNCLES, ())
        });
    }
}
